    _LENIENT_WRITE_CALL_RE: Pattern[str] = re.compile(
        r'["\']?tool["\']?\s*:\s*["\'](?:write_file|save_file|create_file|'
        r'file_write|escribir_archivo|write)["\']'
        r'.*?["\']?(?:path|filename|file|filepath|file_path|ruta|archivo|'
        r'nombre_archivo)["\']?\s*:\s*["\']([^"\']+?)["\']'
        r'.*?["\']?(?:content|contents|text|code|contenido|c[oó]digo|data|'
        r'body|texto)["\']?\s*:\s*["\'](.*)$',
        re.DOTALL | re.IGNORECASE,
    )
    _LENIENT_READ_CALL_RE: Pattern[str] = re.compile(
        r'["\']?tool["\']?\s*:\s*["\'](?:read_file|file_read|read|leer_archivo|'
        r'open_file|cat|view_file|get_file)["\']'
        r'.*?["\']?(?:path|filename|file|filepath|file_path|ruta|archivo|'
        r'target)["\']?\s*:\s*["\']([^"\']+?)["\']',
        re.DOTALL | re.IGNORECASE,
    )

    @staticmethod
    def _json_unescape_lenient(s: str) -> str:
        """Deshace los escapes JSON habituales de un `content` de código
        aunque el resto del objeto sea JSON inválido (saltos de línea sin
        escapar). No toca `\\uXXXX` — irrelevante en código y raro."""
        out: List[str] = []
        i = 0
        table = {
            "n": "\n", "t": "\t", "r": "\r", '"': '"', "'": "'",
            "/": "/", "\\": "\\", "b": "\b", "f": "\f",
        }
        while i < len(s):
            c = s[i]
            if c == "\\" and i + 1 < len(s):
                out.append(table.get(s[i + 1], "\\" + s[i + 1]))
                i += 2
                continue
            out.append(c)
            i += 1
        return "".join(out)

    @classmethod
    def _extract_lenient_file_call(cls, raw_text: str) -> Optional[dict]:
        """
        Rescata una llamada a write_file/read_file de un JSON que
        `json.loads` no puede parsear (saltos de línea o llaves sin
        escapar en `content` — MEDIDO con el modelo abliterado: ~1/3 de
        las corridas). Solo corre si el texto MENCIONA `"tool"`.
        """
        if not raw_text:
            return None
        probe = raw_text.replace("'", '"')
        if '"tool"' not in probe:
            return None
        wm = cls._LENIENT_WRITE_CALL_RE.search(raw_text)
        if wm:
            path = wm.group(1).strip().strip("`")
            content = wm.group(2)
            content = re.sub(
                r'["\']?\s*\}?\s*\}?\s*(?:```)?\s*$', "", content.rstrip()
            )
            content = cls._json_unescape_lenient(content).strip("\n")
            if path and content:
                return {
                    "tool": "write_file",
                    "parameters": {"path": path, "content": content},
                }
        rm = cls._LENIENT_READ_CALL_RE.search(raw_text)
        if rm:
            path = rm.group(1).strip().strip("`")
            if path:
                return {"tool": "read_file", "parameters": {"path": path}}
        return None

    @classmethod
    def _looks_like_partial_stub(cls, code: str) -> bool:
        """¿`code` es un placeholder ('# ... resto del código original') en
        vez del archivo real? Escribirlo BORRARÍA el archivo existente."""
        if not code or not code.strip():
            return True
        return bool(cls._PARTIAL_STUB_RE.search(code))

    def _sandbox_file_exists(self, rel_path: Optional[str]) -> bool:
        """¿`rel_path` existe como archivo bajo la raíz del ToolSandbox
        (la carpeta de workspace activa)? Nunca lanza."""
        if not rel_path:
            return False
        try:
            sandbox = self.tools.sandbox
            return sandbox.validate_path(rel_path).is_file()
        except Exception:
            return False

    def _read_workspace_file(self, rel_path: str) -> Optional[str]:
        """Contenido crudo de un archivo del workspace, o None si no se
        pudo leer. Nunca lanza."""
        try:
            raw = self.tools.sandbox.read_file_safely(rel_path)
        except Exception:
            return None
        if not isinstance(raw, str) or raw.startswith(
            ("[SANDBOX", "[AVISO", "Error", "[INSTRUCCIÓN")
        ):
            return None
        return raw

    def _most_recent_workspace_py_file(self) -> Optional[str]:
        """Nombre (sin ruta) del archivo .py/.pyw modificado más
        recientemente en la raíz del workspace activo (no recursivo).
        Usado como fallback cuando el OCR de una captura de error no
        pudo extraer un nombre de archivo explícito (p.ej. la imagen
        no incluye un traceback con "File ..."). Nunca lanza.

        Name (no path) of the most recently modified .py/.pyw file at
        the top level of the active workspace (non-recursive). Used as
        a fallback when OCR on an error screenshot couldn't extract an
        explicit filename (e.g. the image has no "File ..." traceback
        line). Never raises.
        """
        try:
            root = self.tools.sandbox.root_dir
            candidates = [
                entry for entry in os.scandir(root)
                if entry.is_file() and entry.name.lower().endswith((".py", ".pyw"))
            ]
            if not candidates:
                return None
            newest = max(candidates, key=lambda entry: entry.stat().st_mtime)
            return newest.name
        except Exception:
            return None

    # BLINDAJE (2026-09-17, pedido explicito del usuario -- "que pueda
    # modificar cualquier archivo que tenga el rango de poder modificar"):
    # generaliza `_most_recent_workspace_py_file` (que solo mira .py/.pyw,
    # y solo se usaba para el carril de OCR sobre capturas de error) a
    # CUALQUIER archivo real dentro del workspace activo -- usado por
    # `_resolve_modify_target` cuando el usuario pide modificar "el
    # codigo"/"el archivo" sin nombrarlo y el archivo en cuestion no es
    # python ni coincide con ninguno de los 3 esqueletos clasicos
    # hardcodeados (snake/pong/flappy_bird) -- el caso real medido: un
    # archivo llamado "import pygame.py" referenciado solo como "el
    # codigo que esta en el workspace". Mismos criterios de exclusion que
    # ya usa el vigilante de workspace (`workspace_watcher.py`,
    # `DEFAULT_EXCLUDED_SUFFIXES`) para no ofrecer jamas un archivo de
    # base de datos/WAL/bytecode como si fuera codigo editable, mas los
    # puntos ocultos (`.gitignore`, etc.) que tampoco son "el codigo" que
    # alguien pide modificar en lenguaje natural.
    _GENERIC_TARGET_EXCLUDED_SUFFIXES = (".db", ".wal", ".pyc", ".pyo")

    # BLINDAJE (patch_orchestrator90, 2026-09-18 -- auditoría a pedido
    # del usuario tras patch_orchestrator89: "eso significa que hay
    # muchas palabras que no estan ahi y que deberian estarlo no?").
    # Calificadores genéricos que el modelo suele pegar al nombre de
    # archivo cuando lo crea (p. ej. "agario_basico.py",
    # "snake_simple.py") pero que el usuario casi nunca repite al
    # referirse al archivo después ("el agario", no "el agario
    # basico") -- usado por `_match_workspace_file_by_phrase` para
    # descartarlos al buscar la ÚNICA palabra distintiva restante del
    # nombre. Lista deliberadamente chica y conservadora (mismo
    # criterio que el resto de estas listas: preferir un falso
    # negativo antes que inflar el riesgo de falso positivo).
    _GENERIC_FILENAME_QUALIFIER_WORDS: "frozenset[str]" = frozenset({
        "basico", "basica", "simple", "demo", "test", "basic",
        "nuevo", "nueva", "final", "version", "juego", "game",
    })

    def _most_recent_workspace_file(self) -> Optional[str]:
        """Nombre (sin ruta) del archivo modificado mas recientemente en
        la raiz del workspace activo (no recursivo), excluyendo archivos
        ocultos y los sufijos de `_GENERIC_TARGET_EXCLUDED_SUFFIXES`.
        Nunca lanza. Ver el BLINDAJE de arriba para el porque."""
        try:
            root = self.tools.sandbox.root_dir
            candidates = [
                entry for entry in os.scandir(root)
                if entry.is_file()
                and not entry.name.startswith(".")
                and not entry.name.lower().endswith(self._GENERIC_TARGET_EXCLUDED_SUFFIXES)
            ]
            if not candidates:
                return None
            newest = max(candidates, key=lambda entry: entry.stat().st_mtime)
            return newest.name
        except Exception:
            return None

    @staticmethod
    def _squish_for_phrase_match(text: str) -> str:
        """
        Normaliza texto para el matcheo "insensible a espacios/puntuación"
        de `_match_workspace_file_by_phrase` (patch_orchestrator90): saca
        espacios y la puntuación más común (".,!?;:'\"") antes de
        comparar. Existe porque el nombre de archivo que el modelo genera
        suele juntar palabras que el usuario después escribe separadas (o
        con un punto, como el nombre real del juego) -- "agario_basico.py"
        vs. el pedido real del usuario "agar io" o "agar.io", ninguno de
        los dos substring literal del otro sin esta normalización.
        """
        return re.sub(r"[.,!?;:'\"]", "", re.sub(r"\s+", "", text or ""))

    def _match_workspace_file_by_phrase(self, user_input: str) -> Optional[str]:
        """
        Nombre (sin ruta) del ÚNICO archivo del workspace cuyo nombre
        (sin extensión, "_" -> " ") aparece TEXTUAL y SEGUIDO dentro del
        pedido del usuario -- p. ej. `boton_juego.py` -> "boton juego",
        que sí aparece seguido en "...workspace de boton juego". BLINDAJE
        (2026-09-17, patch_orchestrator53) para cuando `_most_recent_
        workspace_file` (que solo mira fechas de modificación, nunca
        nombres) queda "secuestrado" por un archivo basura de un intento
        fallido anterior que por casualidad quedó con una fecha de
        modificación más nueva que el archivo real que el usuario nombra
        -- ver el BLINDAJE junto a su único llamador, `_resolve_modify_
        target`, para el caso real medido. Requiere al menos 2 palabras
        en el nombre (evita falsos positivos de un nombre de una sola
        palabra genérica como "juego.py"). Ambiguo (0 o 2+ matches) o
        cualquier error -> None, nunca lanza.

        BLINDAJE (patch_orchestrator90, 2026-09-18 -- auditoría a pedido
        del usuario tras el bug real de patch89, turno "añade cosas al
        codigo agar io y explica que añadiste" sobre `agario_basico.py`
        ya existente): el matcheo original exige la frase COMPLETA
        ("agario basico") TEXTUAL y seguida -- el usuario casi nunca la
        repite así ("agar io", con espacio, o "agar.io", el nombre real
        del juego, ninguno de los dos substring de "agario basico" ni al
        revés). Se agregan DOS fallbacks, en orden, solo si el match
        exacto original no encuentra nada: (1) mismo chequeo pero con
        espacios/puntuación comunes sacados de ambos lados
        (`_squish_for_phrase_match`) -- cubre variantes de espaciado del
        mismo nombre completo; (2) si tras sacar calificadores genéricos
        (`_GENERIC_FILENAME_QUALIFIER_WORDS`, p. ej. "basico") queda
        EXACTAMENTE una palabra distintiva (>= 4 caracteres) en el
        nombre del archivo, alcanza con que ESA sola palabra aparezca
        (mismo chequeo sin espacios/puntuación) -- cubre el caso típico
        de referirse al programa por su nombre corto ("el agario") sin
        repetir el calificador que el modelo le agregó al crearlo. Sigue
        exigiendo unicidad (`len(matches) == 1`) como única red de
        seguridad contra falsos positivos -- no se relajó ese criterio.
        """
        try:
            words = (user_input or "").lower()
            words_squished = self._squish_for_phrase_match(words)
            root = self.tools.sandbox.root_dir
            candidates = [
                entry for entry in os.scandir(root)
                if entry.is_file()
                and not entry.name.startswith(".")
                and not entry.name.lower().endswith(self._GENERIC_TARGET_EXCLUDED_SUFFIXES)
            ]
            matches = []
            for entry in candidates:
                stem = os.path.splitext(entry.name)[0]
                phrase = stem.replace("_", " ").replace("-", " ").strip().lower()
                if " " not in phrase:
                    continue
                matched = bool(phrase) and phrase in words
                if not matched:
                    phrase_squished = self._squish_for_phrase_match(phrase)
                    matched = bool(phrase_squished) and phrase_squished in words_squished
                if not matched:
                    stem_words = [w for w in phrase.split(" ") if w]
                    distinctive = [
                        w for w in stem_words
                        if len(w) >= 4 and w not in self._GENERIC_FILENAME_QUALIFIER_WORDS
                    ]
                    if len(distinctive) == 1 and distinctive[0] in words_squished:
                        matched = True
                if matched:
                    matches.append(entry.name)
            if len(matches) == 1:
                return matches[0]
            return None
        except Exception:
            return None

    def _maybe_prepare_code_fix_from_image(
        self, user_input: str, image_path: str, effective_lang: str
    ) -> Tuple[Optional[str], Optional[str]]:
        """Intenta redirigir un turno con imagen adjunta desde el carril
        VISION (moondream, sin tools ni acceso al archivo real) hacia el
        pipeline normal de código, cuando la imagen parece ser una
        captura de un error/traceback de código Y el usuario pide una
        corrección.

        Se activa SOLO si se cumplen las 3 condiciones:
          1. El texto del usuario sugiere que quiere una corrección
             (verbo de modificar como "corregí"/"arreglá"/"fix", O
             lenguaje de reporte de error como "no funciona"/"error").
          2. El OCR sobre la imagen extrae texto Y ese texto tiene pinta
             de código/error (`ocr_reader.looks_like_code_or_error`).
          3. Se puede resolver un archivo REAL existente en el workspace
             activo — por nombre de archivo detectado en un traceback
             vía OCR, o si no, el .py más reciente del workspace.

        Devuelve SIEMPRE una tupla `(prompt_o_None, reason_code)`:
          - `prompt_o_None`: el `user_input` enriquecido si el redirect se
            activó, o `None` si no.
          - `reason_code`: por qué (o por qué no) — `None` si `wants_fix`
            dio False (caso normal de "describime esta imagen", no vale
            la pena loguearlo); si no, uno de "ocr_unavailable" (no se
            pudo cargar el motor de OCR — típicamente falta
            `pip install rapidocr-onnxruntime`), "ocr_no_text" (el motor
            cargó pero no detectó texto en la imagen), "ocr_not_code"
            (detectó texto pero no tiene pinta de código/error),
            "no_target_file" (parece código pero no hay un .py real en
            el workspace activo al que aplicarlo), u "ok" (redirect
            activado). El llamador (`run_turn`) usa `reason_code` para
            emitir un `PipelineEvent(EventType.LOG, ...)` visible en la
            consola de la UI — así un fallo silencioso de OCR (paquete
            no instalado, etc.) deja de ser una caja negra.

        Si CUALQUIERA de las 3 condiciones falla, `prompt_o_None` es
        `None` y el turno sigue exactamente como antes (carril VISION
        intacto, cero cambio de comportamiento) — el texto OCR es
        tratado siempre como una PISTA no confiable, nunca como la
        verdad; el prompt devuelto le pide explícitamente al modelo que
        lo contraste contra el contenido real del archivo (inyectado más
        adelante vía `_current_file_context`, reusando el mecanismo
        existente de "Lever 1" con solo nombrar el archivo target entre
        backticks).

        Attempts to redirect an image-attached turn away from the
        isolated VISION lane (moondream, no tools, no real file access)
        and into the normal code pipeline, when the image looks like a
        code error/traceback screenshot AND the user is asking for a
        fix. Always returns a `(prompt_or_None, reason_code)` tuple —
        see the Spanish docstring above for the reason codes and why
        the caller logs them. `prompt_or_None` is `None` (zero behavior
        change) if any of the 3 conditions isn't met. OCR text is always
        treated as an untrusted hint, never as ground truth — the
        returned prompt explicitly asks the model to cross-check it
        against the real file content injected later via the existing
        `_current_file_context` mechanism.
        """
        wants_fix = bool(
            self._FILE_MODIFY_VERB_RE.search(user_input)
            or self._ERROR_REPORT_RE.search(user_input)
        )
        if not wants_fix:
            return None, None

        if not ocr_reader.is_ocr_available():
            return None, "ocr_unavailable"

        ocr_text = None
        with contextlib.suppress(Exception):
            ocr_text = ocr_reader.extract_text_from_image(image_path)
        if not ocr_text:
            return None, "ocr_no_text"
        if not ocr_reader.looks_like_code_or_error(ocr_text):
            return None, "ocr_not_code"

        target = None
        traceback_name = ocr_reader.extract_traceback_filename(ocr_text)
        if traceback_name and self._sandbox_file_exists(traceback_name):
            target = traceback_name
        if target is None:
            target = self._most_recent_workspace_py_file()
        if target is None or not self._sandbox_file_exists(target):
            return None, "no_target_file"

        ocr_capped = ocr_text if len(ocr_text) <= 2000 else ocr_text[:2000] + "\n[...]"
        is_en = effective_lang == "English"
        if is_en:
            return (
                f"{user_input}\n\n"
                f"[TEXT DETECTED VIA OCR ON THE ATTACHED SCREENSHOT — OCR can "
                f"misread characters, cross-check it against the actual current "
                f"content of `{target}` below before deciding what's wrong]:\n"
                f"{ocr_capped}\n\n"
                f"Update `{target}` to fix the error above."
            ), "ok"
        return (
            f"{user_input}\n\n"
            f"[TEXTO DETECTADO POR OCR EN LA CAPTURA ADJUNTA — el OCR puede "
            f"reconocer mal algunos caracteres, contrastalo contra el contenido "
            f"actual real de `{target}` de más abajo antes de decidir qué está "
            f"mal]:\n{ocr_capped}\n\n"
            f"Arreglá el error de arriba en `{target}`."
        ), "ok"

    @staticmethod
    def _current_file_context(path: str, content: str, lang: Optional[str]) -> str:
        """Bloque para inyectar el contenido ACTUAL de un archivo que se va
        a MODIFICAR — así el modelo lo edita entero en vez de reemplazarlo
        por lo que recuerde. Se acota a ~4500 chars (un archivo más grande
        no entra en una reescritura completa dentro del num_ctx pinneado —
        para esos, el camino es `read_file` vía el bucle de herramientas).

        BLINDAJE (2026-09-18, patch_orchestrator86 -- turno real, MEDIDO
        vía sovnode.wal/sovnode_debug.log (turno_id
        e68bf945-7f71-45ef-ae71-f1fa918cdb00, "mejora el codigo de doom en
        el workspace", retest en vivo de patch84): el PRIMER `edit_file`
        del turno (pasada 1, 1035 tokens de salida, $0.0307 -- casi la
        mitad del costo total del turno) falló con `[SANDBOX WRITE
        ERROR]` (chars=130 en el WAL; `edit_file_safely` en tools.py sólo
        escribe NADA cuando algún `old_str` no matchea 0 o más de 1 vez,
        ver su docstring), obligando a `read_file` (pasada 2) y un
        `edit_file` de reintento (pasada 3, esta vez con 4 ediciones
        aplicadas con éxito). El turno terminó bien gracias a
        patch_orchestrator57 (la guía de reintento dirigido) y
        patch_orchestrator84 (el cierre no se descontroló) -- pero el
        primer intento fallido, por sí solo, costó casi lo mismo que el
        resto del turno completo. Causa raíz: el modelo SÍ tenía el
        contenido real y completo de `doom.py` en este mismo bloque (3744
        bytes, bien por debajo del recorte de 4500) -- no es un problema
        de contenido viejo/faltante -- sino que reproducir un fragmento
        EXACTO carácter por carácter (mismos espacios/indentación/saltos
        de línea) a partir de texto que acaba de leer es un punto débil
        conocido de los LLM, y la instrucción de acá (y la del header
        general, ver más abajo en `_get_frozen_header`) solo pedía que
        `old_str` fuera "chico y ÚNICO" -- nunca decía explícitamente que
        tenía que ser una cita TEXTUAL de lo que se le acaba de mostrar,
        no una reescritura de memoria. Fix: agregar esa instrucción acá,
        pegada al bloque de contenido real (más precisa que agregarla al
        header general, que no siempre tiene contenido visible delante).
        No elimina el riesgo por completo (sigue siendo una instrucción de
        texto, no una garantía) pero apunta al motivo real de la falla en
        vez de solo a "unicidad", que ya se cumplía."""
        is_en = (lang or "Spanish") == "English"
        body = content if len(content) <= 4500 else content[:4500] + "\n[... recortado ...]"
        if is_en:
            return (
                f"\n\n[CURRENT CONTENT OF `{path}` — apply the requested change to "
                f"THIS. PREFER calling `edit_file` with a small, UNIQUE `old_str` "
                f"(the exact lines being changed, with enough surrounding context to "
                f"match only once) and the corresponding `new_str` — do NOT resend the "
                f"whole file for a localized change. If the change touches several "
                f"separate spots, pass `edits` — a list of {{old_str, new_str}} pairs "
                f"applied in order — in that SAME `edit_file` call instead. Only fall "
                f"back to `write_file` with the WHOLE updated file if the change is "
                f"too large or scattered even for several `edits` entries; never a "
                f"fragment or a placeholder like '# rest of the code' either way. "
                f"IMPORTANT: build `old_str` as a VERBATIM, character-for-character "
                f"quote of the text shown below -- copy it, don't retype it from "
                f"memory or reformat it (same spacing, same indentation, same line "
                f"breaks). A single mismatched space or newline makes the whole call "
                f"fail and nothing gets written]:\n"
                f"```\n{body}\n```"
            )
        return (
            f"\n\n[CONTENIDO ACTUAL DE `{path}` — aplicá el cambio pedido sobre ESTO. "
            f"PREFERÍ llamar a `edit_file` con un `old_str` chico y ÚNICO (las líneas "
            f"exactas que cambian, con el contexto que haga falta alrededor para que "
            f"matcheen en un solo lugar) y el `new_str` correspondiente — NO reenvíes "
            f"el archivo entero para un cambio localizado. Si el cambio toca varios "
            f"lugares distintos, pasá `edits` — una lista de pares {{old_str, new_str}} "
            f"aplicados en orden — en ese MISMO llamado a `edit_file`. Recién si el "
            f"cambio es demasiado grande o disperso incluso para varias entradas de "
            f"`edits`, caé en `write_file` con el archivo COMPLETO actualizado; nunca "
            f"un fragmento ni un placeholder tipo '# resto del código' en ningún "
            f"caso. IMPORTANTE: armá `old_str` como una cita TEXTUAL, carácter por "
            f"carácter, del texto que se muestra abajo -- copialo, no lo reescribas "
            f"de memoria ni lo reformatees (mismos espacios, misma indentación, "
            f"mismos saltos de línea). Un solo espacio o salto de línea que no "
            f"coincida hace fallar todo el llamado y no se escribe nada]:\n"
            f"```\n{body}\n```"
        )

    @staticmethod
    def _extract_code_payload(text: str) -> Tuple[Optional[str], str]:
        """
        El bloque de código con fence más grande que NO sea un JSON de
        tool-call. Devuelve `(código, hint_de_lenguaje)` o `(None, "")`.
        """
        if not text or "```" not in text:
            return None, ""
        best: Optional[str] = None
        best_lang = ""
        for m in re.finditer(r"```([A-Za-z0-9_+.\-]*)[ \t]*\r?\n?(.*?)```", text, re.DOTALL):
            lang = (m.group(1) or "").strip().lower()
            body = (m.group(2) or "").strip("\r\n")
            if not body.strip():
                continue
            head = body.lstrip()[:120]
            if lang == "json" or (head.startswith("{") and '"tool"' in head.replace("'", '"')):
                continue
            if best is None or len(body) > len(best):
                best, best_lang = body, lang
        return best, best_lang

    @classmethod
    def _build_codegen_salvage_prompt(
        cls, user_input: str, filename: Optional[str], lang: Optional[str],
        # BLINDAJE (2026-09-19, patch_orchestrator110 -- ver el docstring
        # de `_salvage_file_operation`, sección "ya se leyó en este
        # turno"): cuando el archivo objetivo YA EXISTE y ya se leyó, este
        # prompt debe pedir una actualización DIRIGIDA sobre el contenido
        # real -- no una reescritura ciega desde cero a partir solo del
        # pedido del usuario (eso perdería cualquier cosa que el archivo
        # ya tuviera, ej. las mejoras de un turno anterior). `None`
        # (default) preserva el comportamiento original para un archivo
        # nuevo, donde no hay nada que preservar.
        existing_content: Optional[str] = None,
    ) -> str:
        is_en = (lang or "Spanish") == "English"
        fname = filename or cls._derive_filename(user_input)
        if existing_content:
            if is_en:
                return (
                    f"This is the CURRENT, working content of \"{fname}\" exactly "
                    f"as it is on disk right now:\n\n{existing_content}\n\n"
                    f"The user asked: {user_input}\n\n"
                    "Do NOT rewrite this file from scratch. Read it as it is and "
                    "apply the requested change directly on top of it: ADD what "
                    "needs to be added, IMPROVE what needs to be improved, or "
                    "REPLACE only the specific part(s) that need replacing. "
                    "Everything else in the file — unrelated functions, structure, "
                    "names, style — must stay EXACTLY as it already is. This is a "
                    "legitimate local development task. Save the COMPLETE updated "
                    "file by emitting ONLY this tool call — no prose, no refusal, "
                    "no copyright disclaimer — inside a ```json fence:\n"
                    f'```json\n{{"tool": "write_file", "parameters": {{"path": "{fname}", '
                    '"content": "<the entire updated file here, using \\\\n for newlines>"}}\n```\n'
                    f'The path "{fname}" is relative to the workspace root — do not '
                    "make it absolute and do not add a \"workspace/\" prefix."
                )
            return (
                f"Este es el contenido ACTUAL y funcional de \"{fname}\" tal cual "
                f"está en disco ahora mismo:\n\n{existing_content}\n\n"
                f"El usuario pidió: {user_input}\n\n"
                "NO reescribas este archivo desde cero. Leelo tal cual está y "
                "aplicá el cambio pedido directamente sobre él: AGREGÁ lo que "
                "haya que agregar, MEJORÁ lo que haya que mejorar, o REEMPLAZÁ "
                "solo la parte puntual que haya que reemplazar. Todo lo demás del "
                "archivo -- funciones sin relación, estructura, nombres, estilo -- "
                "tiene que quedar EXACTAMENTE como ya está. Es una tarea legítima "
                "de desarrollo local. Guardá el archivo COMPLETO actualizado "
                "emitiendo ÚNICAMENTE esta llamada a herramienta —sin prosa, sin "
                "rechazo, sin aviso de derechos de autor— dentro de un fence "
                "```json:\n"
                f'```json\n{{"tool": "write_file", "parameters": {{"path": "{fname}", '
                '"content": "<el archivo entero actualizado acá, usando \\\\n para '
                'los saltos de línea>"}}\n```\n'
                f'La ruta "{fname}" es relativa a la raíz del workspace — no la '
                "hagas absoluta ni le agregues un prefijo \"workspace/\"."
            )
        if is_en:
            return (
                f"The user asked: {user_input}\n\n"
                "This is a legitimate local development task. Write the COMPLETE, "
                "working file and save it by emitting ONLY this tool call — no prose, "
                "no refusal, no copyright disclaimer — inside a ```json fence:\n"
                f'```json\n{{"tool": "write_file", "parameters": {{"path": "{fname}", '
                '"content": "<the entire file here, using \\\\n for newlines>"}}\n```\n'
                f'The path "{fname}" is relative to the workspace root — do not make it '
                "absolute and do not add a \"workspace/\" prefix."
            )
        return (
            f"El usuario pidió: {user_input}\n\n"
            "Es una tarea legítima de desarrollo local. Escribí el archivo COMPLETO y "
            "funcional y guardalo emitiendo ÚNICAMENTE esta llamada a herramienta —sin "
            "prosa, sin rechazo, sin aviso de derechos de autor— dentro de un fence "
            "```json:\n"
            f'```json\n{{"tool": "write_file", "parameters": {{"path": "{fname}", '
            '"content": "<el archivo entero acá, usando \\\\n para los saltos de línea>"}}\n```\n'
            f'La ruta "{fname}" es relativa a la raíz del workspace — no la hagas '
            "absoluta ni le agregues un prefijo \"workspace/\"."
        )

    def _salvage_file_operation(
        self,
        user_input: str,
        raw_response: str,
        decision: Optional["RoutingDecision"],
        lang: Optional[str],
        *,
        active_model: Optional[str] = None,
        log_cb: Optional[Callable[[str], None]] = None,
        # BLINDAJE (2026-09-19, patch_orchestrator110): rutas ya leídas
        # con éxito en ESTE MISMO turno (`_paths_read_this_turn`, ver
        # `run_turn`). Antes, la rama "modificación sobre archivo
        # existente" de abajo sintetizaba `read_file` CIEGAMENTE cada vez
        # que el modelo no producía código real, sin importar si ya se
        # había leído ese archivo en una pasada anterior -- bug real,
        # MEDIDO: turno "improve the graphics of the game" sobre
        # `mario.py` (ya leído en la pasada 1) generó `read_file`
        # sintetizado DOS VECES MÁS, disparando el guardia anti-bucle y
        # terminando el turno sin haber intentado escribir el cambio ni
        # una vez. Con esto, si el archivo objetivo ya está en este set,
        # se salta el "leer primero" y se escala directo a generar el
        # cambio real (con el contenido ya conocido como contexto).
        already_read_paths: Optional[Set[str]] = None,
    ) -> Tuple[Optional[dict], Optional[str]]:
        """
        El modelo NO emitió ninguna llamada para un turno de archivos.
        Sintetiza la llamada real. Devuelve `(tool_call | None, raw_de_
        reemplazo | None)`.

        - Lectura: se sintetiza `read_file(<archivo>)` o `list_dir(".")`
          directo — leer no necesita la cooperación del modelo.
        - Escritura: si el modelo pegó el código en prosa, se arma
          `write_file` con ese código. Si lo rechazó o no produjo código,
          se regenera el contenido con el modelo general/sin-censura (el
          coder es justo el que rechaza) y se arma la llamada con eso.
          Si el archivo objetivo YA EXISTE, esa regeneración pide una
          actualización DIRIGIDA sobre el contenido real (ver
          `_build_codegen_salvage_prompt`), no una reescritura ciega.
        """
        is_write = self._is_file_write_turn(user_input, decision)
        is_read = self._is_file_read_turn(user_input, decision)
        if not (is_write or is_read):
            return None, None

        def _log(msg: str) -> None:
            if log_cb is not None:
                with contextlib.suppress(Exception):
                    log_cb(msg)

        filename = self._extract_target_filename(user_input, raw_response or "")
        if not filename:
            # BLINDAJE (2026-09-17, patch_orchestrator52 -- bug real, MEDIDO vía
            # sovnode.wal (turno_id c79851d1-02b1-4fff-a808-e542ea5fd944): "mejora
            # el codigo boton juego en el workspace agregando cosas nuevas", con
            # `boton_juego.py` YA existente en el sandbox -- el modelo no emitió
            # ninguna llamada (por eso se llegó acá, a `_salvage_file_operation`),
            # `_extract_target_filename` no encontró ningún nombre EXPLÍCITO con
            # extensión ni en el pedido ni en la respuesta cruda, así que
            # `filename` quedaba en `None` -- más abajo, `target_exists =
            # self._sandbox_file_exists(filename)` daba False (nunca existe un
            # archivo con nombre `None`), así que la rama "es una modificación y
            # el archivo YA existe -> leerlo primero" nunca se activaba, aunque
            # `is_modify` fuera True -- se caía derecho al último fallback,
            # `self._derive_filename(user_input, ...)`, que arma un nombre nuevo
            # slugificando las palabras del pedido ("mejora", "boton", "juego",
            # "agregando" -> `mejora_boton_juego_agregando.py`) -- exactamente el
            # mismo bug #7 ("Can you improve the snake game in there" creando
            # `snake_game.py` en vez de tocar `snake.py`) que `_resolve_modify_
            # target` ya resuelve para la generación inicial (fallback a un
            # esqueleto conocido y, si no, al archivo modificado más
            # recientemente cuando el pedido usa un verbo de modificar como
            # "mejora") -- pero esta función tenía su PROPIA resolución de
            # nombre, duplicada y sin esos mismos fallbacks, así que nunca se
            # benefició del fix. Reutilizar `_resolve_modify_target` en vez de
            # reimplementar la misma lógica acá es lo que evita que vuelva a
            # divergir.
            filename, _ = self._resolve_modify_target(user_input, is_write)

        if is_read and not is_write:
            if filename:
                _log(f"Blindaje de archivos: sintetizando read_file('{filename}').")
                return {"tool": "read_file", "parameters": {"path": filename}}, None
            _log("Blindaje de archivos: sin nombre de archivo — sintetizando list_dir('.').")
            return {"tool": "list_dir", "parameters": {"path": "."}}, None

        code_payload, lang_hint = self._extract_code_payload(raw_response or "")
        refused = self._looks_like_refusal(raw_response or "")
        is_modify = bool(self._FILE_MODIFY_VERB_RE.search(user_input or ""))
        target_exists = self._sandbox_file_exists(filename)
        stub = self._looks_like_partial_stub(code_payload or "")

        _target_already_read = bool(
            already_read_paths and filename and filename in already_read_paths
        )
        if is_modify and target_exists and (not code_payload or stub or refused):
            if not _target_already_read:
                _log(
                    f"Blindaje de archivos: 'modificar {filename}' — leyendo el "
                    "archivo actual primero (evita reemplazarlo por un stub)."
                )
                return {"tool": "read_file", "parameters": {"path": filename}}, None
            # BLINDAJE (2026-09-19, patch_orchestrator110 -- ver el
            # comentario de `already_read_paths` en la firma): este mismo
            # archivo ya se leyó en una pasada anterior de este turno --
            # releerlo de nuevo no le da al modelo ningún dato que no
            # tuviera ya, y es justo lo que producía el bucle real medido
            # ("read_file" repetido hasta el guardia anti-bucle). En vez
            # de repetir la lectura, se sigue de largo hacia la
            # regeneración de abajo, que ahora recibe el contenido real
            # del archivo (ver `existing_content` en la llamada a
            # `_build_codegen_salvage_prompt`) para aplicar el cambio
            # dirigido en vez de reescribir a ciegas.
            _log(
                f"Blindaje de archivos: 'modificar {filename}' ya se leyó en "
                "este turno — generando el cambio directamente sobre el "
                "contenido real en vez de releerlo de nuevo."
            )

        if (not code_payload) or refused or stub:
            if refused:
                other_model = (
                    self.coder_model
                    if active_model == self.general_model
                    else self.general_model
                )
                regen_candidates = [active_model or self.general_model, other_model]
            else:
                regen_candidates = [active_model or self.general_model]

            regen = ""
            for attempt_num, regen_model in enumerate(regen_candidates):
                _log(
                    "Blindaje de archivos: el modelo "
                    + ("rechazó el pedido" if refused else "no produjo código")
                    + f" — regenerando el contenido con {regen_model}"
                    + (" (mismo modelo, prompt más directo — sin swap de VRAM)"
                       if refused and attempt_num == 0 else
                       " (el reintento con el mismo modelo no alcanzó — escalando "
                       "al otro modelo)" if refused and attempt_num > 0 else "")
                    + "."
                )
                with contextlib.suppress(Exception):
                    regen = self._call_llm(
                        self._build_codegen_salvage_prompt(
                            user_input, filename, lang,
                            existing_content=(
                                self._read_workspace_file(filename)
                                if target_exists and filename else None
                            ),
                        ),
                        target_model=regen_model,
                        lang_override=lang,
                        system_override=self._get_file_ops_system_prompt(
                            "English" if (lang or "Spanish") == "English" else "Spanish"
                        ),
                        num_predict_override=self._effective_codegen_num_predict(),
                        log_cb=log_cb,
                        perf_label="FileSalvage",
                    )
                if regen and not regen.lstrip().startswith("[ERROR"):
                    direct = self.extract_tool_call(regen)
                    if direct and direct.get("tool") in ("write_file", "read_file", "list_dir"):
                        dcontent = direct.get("parameters", {}).get("content")
                        if direct["tool"] != "write_file" or not self._looks_like_partial_stub(dcontent or ""):
                            return direct, None
                    payload2, hint2 = self._extract_code_payload(regen)
                    if payload2 and not self._looks_like_partial_stub(payload2):
                        code_payload, lang_hint = payload2, hint2
                        break

        if not code_payload or self._looks_like_partial_stub(code_payload):
            # BLINDAJE (2026-09-19, patch_orchestrator110): mismo criterio
            # que la rama de arriba -- si el archivo YA se leyó en este
            # turno, releerlo de nuevo acá sería el mismo bucle real
            # medido (la regeneración de arriba ya tuvo su oportunidad
            # con el contenido real como contexto y de todos modos no
            # produjo código usable). Best-effort: se rinde limpio
            # (`None, None`) en vez de insistir con otro `read_file`.
            if is_modify and target_exists and filename and not _target_already_read:
                return {"tool": "read_file", "parameters": {"path": filename}}, None
            return None, None

        if not filename:
            filename = self._derive_filename(user_input, lang_hint)

        _log(
            f"Blindaje de archivos: sintetizando write_file('{filename}') "
            f"({len(code_payload)} bytes de código)."
        )
        return (
            {"tool": "write_file", "parameters": {"path": filename, "content": code_payload}},
            None,
        )

    @staticmethod
    def _factual_enumeration_caution(lang: Optional[str]) -> str:
        is_en = (lang or "Spanish") == "English"
        if is_en:
            return (
                "\n\n[NOTICE — UNVERIFIED FACTUAL RECALL]: this request asks you to "
                "enumerate several established technical facts (laws, formulas, "
                "principles) with no web context or verification tool available this "
                "turn. Before writing each item, confirm internally that it is real "
                "and genuinely recognized in the field. If you are not confident an "
                "additional item exists as you would describe it, it is better to "
                "give FEWER items, all correct, than to reach the requested count by "
                "inventing a name, formula, or attribution that sounds plausible.\n\n"
                "If the request names a specific FIELD or DISCIPLINE (e.g. "
                "'of mathematics', 'of physics'), every item must strictly belong to "
                "THAT discipline — a real, correctly-named law from a DIFFERENT "
                "discipline is still the wrong answer, even though it is a genuine "
                "fact. Also never restate the same underlying law or equation twice "
                "under a different name just to reach the requested count — each "
                "item must be substantively distinct from every other item you give."
                "\n\nAlso, never produce more than 8 to 10 items in total, even if "
                "the request does not specify a count. If you notice you are about "
                "to repeat the same title or structure while only changing a "
                "symbol, a trigonometric function, or a subscript, STOP the list "
                "right there instead of continuing — that is a sign no genuinely "
                "distinct real items remain, not an invitation to keep generating "
                "variants. Never invent a law name that merely sounds plausible "
                "(for example attributing to a well-known scientist a law they did "
                "not formulate) just to make the list look more complete."
            )
        return (
            "\n\n[AVISO — RECUPERACIÓN FACTUAL SIN VERIFICACIÓN]: este pedido es "
            "enumerar varios hechos técnicos establecidos (leyes, fórmulas, "
            "principios) sin contexto web ni herramienta de verificación "
            "disponible en este turno. Antes de escribir cada elemento, confirmá "
            "internamente que es real y está genuinamente reconocido en la "
            "disciplina. Si no estás seguro de que un elemento adicional exista tal "
            "como lo ibas a describir, es preferible entregar MENOS elementos, "
            "todos correctos, que completar la cantidad pedida inventando un "
            "nombre, una fórmula o una atribución que suene plausible.\n\n"
            "Si el pedido nombra una DISCIPLINA concreta (por ejemplo 'de la "
            "matemática', 'de la física'), cada elemento debe pertenecer "
            "estrictamente a ESA disciplina — una ley real y bien nombrada pero de "
            "OTRA disciplina sigue siendo una respuesta incorrecta, aunque sea un "
            "hecho genuino. Tampoco repitas la misma ley o ecuación de fondo dos "
            "veces bajo un nombre distinto solo para alcanzar la cantidad pedida — "
            "cada elemento debe ser sustancialmente distinto de los demás que des."
            "\n\nAdemás, no generes más de 8 a 10 elementos en total, incluso si el "
            "pedido no aclara una cantidad. Si notás que estás por repetir el mismo "
            "título o estructura variando solo un símbolo, una función "
            "trigonométrica o un subíndice, DETENÉ la lista ahí mismo en vez de "
            "continuar — esa es una señal de que ya no quedan elementos reales "
            "distintos, no una invitación a seguir generando variantes. Nunca "
            "inventes un nombre de ley que suene plausible (por ejemplo atribuyendo "
            "a un científico conocido una ley que no formuló) solo para que la "
            "lista parezca más completa."
        )

    def _llm_router_classify(self, user_input: str) -> Optional[RoutePath]:
        """
        Clasificación fast/slow vía LLM (self.router_model, 0.5B por
        defecto) — ver la nota junto a ROUTER_LLM_NUM_PREDICT.

        A propósito NO se le pasa historial de conversación ni contexto
        web — solo el mensaje crudo de este turno. Ver Sección 18 (bug
        real de historial envenenado reinyectado como contexto): un
        router que solo ve el turno actual no puede sufrir esa misma
        clase de bug.

        Devuelve None ante CUALQUIER fallo — HTTP, conexión, o una
        respuesta que no contenga 'fast_path'/'slow_path' reconocible —
        para que el llamador (_classify_turn) caiga a IntentRouter
        determinista sin romper el turno. Reusa la convención
        `.startswith("[ERROR")` que _call_llm_raw ya documenta y que el
        resto de este archivo ya chequea.

        Todo el cuerpo va además envuelto en un try/except amplio, a
        propósito: cualquier excepción cruda acá (no solo el sentinel
        "[ERROR" que _call_llm_raw devuelve en su propio try/except)
        también debe degradar a IntentRouter, nunca tumbar el turno
        entero — mismo principio que _call_llm_raw ya aplica un nivel más
        abajo. Esto también es lo que deja pasar, sin romper, a un
        Orchestrator armado a mano en un test (object.__new__) al que le
        falte algún atributo de la cadena de _call_llm_raw — un entorno
        de test sin Ollama real de por medio debe comportarse igual que
        Ollama caído: cae al router determinista, no revienta.
        """
        router_text = user_input or ""
        if len(router_text) > self.ROUTER_LLM_MAX_INPUT_CHARS:
            router_text = router_text[-self.ROUTER_LLM_MAX_INPUT_CHARS:]
        try:
            raw, _tokens, _reason = self._call_llm_raw(
                router_text,
                target_model=self.router_model,
                temperature_override=self.ROUTER_LLM_TEMPERATURE,
                num_predict_override=self.ROUTER_LLM_NUM_PREDICT,
                system_override=self._ROUTER_LLM_SYSTEM_PROMPT,
                stop=["\n"],
                keep_alive_override="30m",
                perf_label="Router0.5B",
                timeout_override=self.ROUTER_LLM_TIMEOUT_SECONDS,
                force_local=True,
            )
        except Exception as exc:
            logger.warning(
                "🧭 [Router0.5B] excepción inesperada clasificando con %s "
                "(%s) — usando IntentRouter determinista.",
                getattr(self, "router_model", "?"), exc,
            )
            return None

        if raw.lstrip().startswith("[ERROR"):
            logger.warning(
                "🧭 [Router0.5B] Ollama falló clasificando con %s (%s) — "
                "usando IntentRouter determinista.",
                self.router_model, raw,
            )
            return None

        normalized = raw.strip().lower()
        if "slow_path" in normalized or normalized.startswith("slow"):
            return RoutePath.SLOW_PATH
        if "fast_path" in normalized or normalized.startswith("fast"):
            return RoutePath.FAST_PATH

        logger.warning(
            "🧭 [Router0.5B] respuesta no interpretable de %s: %r — "
            "usando IntentRouter determinista.",
            self.router_model, raw,
        )
        return None

    def _classify_turn(self, user_input: str) -> RoutingDecision:
        """
        Decisión de ruteo real usada por run_turn/process_turn.

        Corre SIEMPRE IntentRouter.classify() (determinista, cuesta
        microsegundos) para obtener tags/score/reason — ver la nota junto
        a ROUTER_LLM_NUM_PREDICT sobre por qué esas señales NO vienen del
        modelo de 0.5B. Además, SIEMPRE intenta una clasificación vía LLM
        (_llm_router_classify): si responde con éxito, su veredicto de
        `path` reemplaza al determinista — CON UNA EXCEPCIÓN (ver
        BLINDAJE de consenso más abajo, en el cuerpo del método): no
        puede DEGRADAR un slow_path determinista que ya cruzó
        SLOW_PATH_THRESHOLD a fast_path. En cualquier otro caso (upgrade
        fast->slow, o acuerdo) sigue siendo "reemplazo total" — pedido
        original del usuario, ahora acotado tras un bug real medido (ver
        abajo). Si la llamada al 0.5B falla o no es interpretable, se usa
        el `path` determinista sin cambios. `reason` documenta siempre
        qué pasó, para que quede visible en la consola de logs de la UI.
        """
        start = time.perf_counter()
        deterministic = self._router.classify(user_input)
        skeleton_shortcut = self._resolve_skeleton_match(user_input, deterministic) is not None
        formula_discovery_shortcut = self._resolve_formula_discovery_match(
            user_input, deterministic
        )
        if skeleton_shortcut or formula_discovery_shortcut:
            elapsed = (time.perf_counter() - start) * 1000
            shortcut_label = (
                "esqueleto local (Palanca 1)"
                if skeleton_shortcut
                else "motor de descubrimiento de fórmulas"
            )
            return replace(
                deterministic,
                elapsed_ms=elapsed,
                reason=(
                    f"{deterministic.reason} [Router0.5B saltado: el turno se "
                    f"resuelve con el {shortcut_label}, decision.path "
                    f"no se usa en esa rama]"
                ),
            )
        # BLINDAJE (Fix #2, MEDIDO 2026-09-11, video de cuellos de
        # botella): combinado con la regla de consenso más abajo, cuando
        # `deterministic.path is RoutePath.SLOW_PATH` el veredicto del
        # 0.5B NUNCA puede cambiar el `path` final — o coincide (se
        # mantiene slow_path) o dice fast_path y queda bloqueado por el
        # BLINDAJE de consenso (no puede degradar). En ambos casos el
        # resultado final es idéntico: slow_path. Pagar una ronda entera
        # y en serie del Router0.5B — con su propio VRAM swap, ~11s
        # medidos en el video — para un veredicto que no puede alterar la
        # decisión es el mismo desperdicio que el atajo de esqueleto/
        # fórmulas de arriba, y es seguro por el mismo motivo: se puede
        # probar mirando el código (regla de consenso, más abajo) que el
        # resultado no cambia.
        if deterministic.path is RoutePath.SLOW_PATH:
            elapsed = (time.perf_counter() - start) * 1000
            return replace(
                deterministic,
                elapsed_ms=elapsed,
                reason=(
                    f"{deterministic.reason} [Router0.5B saltado: "
                    f"IntentRouter ya cruzó SLOW_PATH_THRESHOLD "
                    f"({self._router.SLOW_PATH_THRESHOLD}) con score="
                    f"{deterministic.score:+.2f} — el veredicto del 0.5B no "
                    f"puede cambiar el resultado (regla de consenso: no "
                    f"puede degradar un slow_path determinista)]"
                ),
            )

        llm_path = self._llm_router_classify(user_input)
        elapsed = (time.perf_counter() - start) * 1000
        router_model_label = getattr(self, "router_model", "?")

        if llm_path is None:
            return replace(
                deterministic,
                elapsed_ms=elapsed,
                reason=(
                    f"{deterministic.reason} [Router0.5B ({router_model_label}) "
                    f"no disponible o respuesta no interpretable — se usó "
                    f"IntentRouter determinista]"
                ),
            )

        # BLINDAJE de consenso (bug real, MEDIDO en video 2026-09-02):
        # antes, el veredicto del LLM router (0.5B) reemplazaba el `path`
        # determinista de forma TOTAL, "coincida o no" — incluso cuando
        # IntentRouter ya había cruzado SLOW_PATH_THRESHOLD con una señal
        # real. Turno capturado: "Deriva la ecuación de Schrödinger
        # independiente del tiempo para un pozo de potencial infinito y
        # muestra la función de onda resultante." → IntentRouter devolvía
        # slow_path (score=+3.00, por encima del umbral), pero el 0.5B lo
        # evaluó como fast_path y esa fue la decisión FINAL — una
        # derivación física completa terminó en el carril LEAN de una
        # sola pasada, con el techo de num_predict más chico, en vez del
        # plan que el propio `_ROUTER_LLM_SYSTEM_PROMPT` pide para
        # "RESOLVER, CALCULAR o DERIVAR una expresión matemática
        # concreta". El reemplazo total además dejaba un `RoutingDecision`
        # internamente inconsistente: `score`/`tags` seguían siendo los
        # del determinista (slow_path), pero `path` decía fast_path.
        #
        # Regla de consenso: el 0.5B puede seguir UPGRADEANDO libremente
        # (fast_path determinista -> slow_path del 0.5B se respeta
        # siempre — cuesta más cómputo pero nunca empeora la respuesta, y
        # es precisamente lo que corrige falsos NEGATIVOS del
        # determinista). Lo que ya NO puede hacer es DEGRADAR un
        # slow_path determinista que cruzó el umbral
        # (`deterministic.path is RoutePath.SLOW_PATH`, equivalente a
        # `deterministic.score >= self._router.SLOW_PATH_THRESHOLD`) a
        # fast_path: un modelo de 0.5B es, por diseño, el clasificador
        # menos confiable de los dos — vetarle solo la dirección de
        # downgrade preserva su utilidad real (subir de carril ante un
        # falso negativo determinista) sin heredar sus propios falsos
        # negativos.
        if deterministic.path is RoutePath.SLOW_PATH and llm_path is RoutePath.FAST_PATH:
            return replace(
                deterministic,
                elapsed_ms=elapsed,
                reason=(
                    f"{deterministic.reason} [Router0.5B ({router_model_label}): "
                    f"'fast_path' NO pudo degradar la decisión — IntentRouter ya "
                    f"había cruzado SLOW_PATH_THRESHOLD "
                    f"({self._router.SLOW_PATH_THRESHOLD}) con score="
                    f"{deterministic.score:+.2f}; se mantiene slow_path]"
                ),
            )

        agreement = "coincide con" if llm_path == deterministic.path else "SOBRESCRIBE"
        return replace(
            deterministic,
            path=llm_path,
            elapsed_ms=elapsed,
            reason=(
                f"{deterministic.reason} [Router0.5B ({router_model_label}): "
                f"'{llm_path.value}' {agreement} IntentRouter "
                f"'{deterministic.path.value}']"
            ),
        )

    def _select_model_for_decision(self, decision: RoutingDecision) -> str:
        """
        BLINDAJE (2026-09-03, reactivado a pedido explícito del usuario —
        ver RESPONSE_MODEL/CODER_MODEL): vuelve a haber dos modelos.
        `self.coder_model` se elige SOLO cuando el router determinista
        (`IntentRouter`, no el LLM de 0.5B — ver `_classify_turn`) marcó
        `SignalTag.CODE_COMPLEX` para este turno; cualquier otro caso cae
        en `self.general_model` (el "sin censura" por defecto).

        Se reusa la MISMA señal que ya gatilla el recordatorio de
        herramientas de Fase E (`_EXISTING_FILE_REFERENCE_RE` +
        `SignalTag.CODE_COMPLEX`, ver `run_turn`/`process_turn`) — no una
        señal nueva — para que "el turno es de código" tenga una única
        fuente de verdad en todo el pipeline.

        A diferencia de la versión pre-2026-08-27 de esta función, NO se
        reactiva `CODER_SYSTEM_PROMPT` ni el parámetro `is_coder` del
        protocolo de generación: el carril LEAN de una sola pasada sigue
        usando el mismo `_get_fastpath_system_prompt` (con el schema de
        herramientas) para AMBOS modelos — ver el comentario extenso junto
        a `CODER_MODEL`. El BLINDAJE viejo (no mandar MATH_EXPRESSION en
        solitario al coder para que no heredara CODER_SYSTEM_PROMPT +
        DEV_MODE_OVERRIDE y colgara un bloque ```python — bug real,
        MEDIDO) sigue sin aplicar por la misma razón: ese prompt nunca se
        activa en este pipeline, cambie o no el modelo de pesos.
        """
        if SignalTag.CODE_COMPLEX in decision.tags:
            return self.coder_model
        return self.general_model

    def _emit_alert(self, message: str, level: str = "info") -> None:
        alert = ProactiveAlert(message=message, level=level)
        try:
            self.alert_queue.put_nowait(alert)
        except queue.Full:
            with contextlib.suppress(queue.Empty):
                self.alert_queue.get_nowait()
            with contextlib.suppress(queue.Full):
                self.alert_queue.put_nowait(alert)

    def _extract_math_candidate(self, text: str) -> Optional[str]:
        if not text or not text.strip():
            return None

        normalized = _MULTI_SPACE_RE.sub(" ", text.strip())

        equation_match = _EQUATION_CANDIDATE_RE.search(normalized)
        if equation_match:
            candidate = equation_match.group(0)
            return self._sanitize_math_candidate(candidate)

        command_stripped = _MATH_LEADING_NOISE_RE.sub("", normalized)

        function_match = _FUNCTION_EXPRESSION_RE.search(command_stripped)
        if function_match:
            candidate = function_match.group(0)
            return self._sanitize_math_candidate(candidate)

        algebraic_match = _ALGEBRAIC_EXPRESSION_RE.search(command_stripped)
        if algebraic_match:
            candidate = algebraic_match.group(0)
            return self._sanitize_math_candidate(candidate)

        if _MATH_COMMAND_RE.search(normalized):
            fallback = _MATH_LEADING_NOISE_RE.sub("", normalized)
            fallback = self._sanitize_math_candidate(fallback)

            if fallback and re.search(r"[\d\+\-\*/\^\(\)]", fallback):
                return fallback

        return None

    def _sanitize_math_candidate(self, candidate: str) -> str:
        if not candidate:
            return ""

        sanitized = _MATH_LEADING_NOISE_RE.sub("", candidate)
        sanitized = _MATH_TRAILING_NOISE_RE.sub("", sanitized)
        sanitized = _MULTI_SPACE_RE.sub(" ", sanitized).strip()
        sanitized = sanitized.strip(" \t\n.,;:!?")

        return sanitized

    def _dispatch_slow_path(
        self,
        text: str,
        decision: RoutingDecision,
    ) -> Tuple[TurnOutcome, List[EngineResult], bool]:
        tags = set(decision.tags)
        results: List[EngineResult] = []
        web_context_used = False

        if (
            SignalTag.LOGIC_AUDIT in tags
            or SignalTag.CONCEPTUAL_DENSE in tags
        ):
            fuzz_result = self._fuzzer.audit(text)
            results.append(fuzz_result)
            return TurnOutcome.SLOW_PATH_FUZZER, results, web_context_used

        if SignalTag.LSC_INFERENCE in tags:
            lsc_result = self._lsc_engine.infer(text)
            results.append(lsc_result)
            return TurnOutcome.SLOW_PATH_LSC, results, web_context_used

        if SignalTag.MATH_EXPRESSION in tags and SignalTag.CODE_COMPLEX not in tags:
            candidate = self._extract_math_candidate(text)

            if candidate:
                if "=" in candidate:
                    cas_result = self._cas.solve_equation(candidate)
                else:
                    cas_result = self._cas.simplify_expression(candidate)

                results.append(cas_result)
                return TurnOutcome.SLOW_PATH_CAS, results, web_context_used

        if SignalTag.CODE_COMPLEX in tags:
            code_match = _CODE_FENCE_RE.search(text)

            if code_match:
                sandbox_result = self._sandbox.run(code_match.group(1).strip())
                results.append(sandbox_result)
                return TurnOutcome.SLOW_PATH_SANDBOX, results, web_context_used

        return TurnOutcome.SLOW_PATH_GENERIC_REASONING, results, web_context_used

    def _get_fuzz_summary(self, result: FuzzingResult) -> str:
        summary = getattr(result, "summary", None)
        if summary:
            return str(summary)

        detail = getattr(result, "detail", None)
        if detail:
            return str(detail)

        return "El auditor no entregó detalles adicionales."

    def _is_critical_search_requirement(self, requirement: Any) -> bool:
        priority = getattr(requirement, "priority", None)
        return priority in (1, "1", "P1", "p1")

    def _recursive_self_critique(
        self,
        hypothesis: str,
        context: str,
        max_iterations: Optional[int] = None,
        target_model: Optional[str] = None,
        lang: Optional[str] = None,
    ) -> Tuple[str, Optional[FuzzingResult], bool]:
        iterations = max_iterations or self.MAX_SELF_CRITIQUE_ITERATIONS
        current_hypothesis = hypothesis.strip()
        last_fuzz_result: Optional[FuzzingResult] = None
        web_context_used = False

        for _ in range(max(1, iterations)):
            fuzz_result = self._fuzzer.audit(current_hypothesis)
            last_fuzz_result = fuzz_result

            if fuzz_result.verdict == FuzzingVerdict.ROBUST:
                break

            requirements = getattr(fuzz_result, "search_requirements", ())
            critical_requirements = [
                requirement
                for requirement in requirements
                if self._is_critical_search_requirement(requirement)
            ]

            web_evidence = ""

            if critical_requirements:
                query = " ".join(
                    (
                        getattr(requirement, "query", "")
                        or getattr(requirement, "claim", "")
                    ).strip()
                    for requirement in critical_requirements
                ).strip()

                if query:
                    try:
                        # Bug real, MEDIDO: esta llamada nunca pasaba `lang`,
                        # así que search_web_context() siempre caía a su
                        # default (None -> español) sin importar el idioma
                        # de la UI. `lang` (parámetro de este método) casi
                        # nunca llega con valor real desde el único call
                        # site actual (_self_repair, más arriba en este
                        # archivo, no lo pasa) — por eso se usa como
                        # override opcional y se cae a self.current_language
                        # (idioma de sesión, siempre disponible), igual que
                        # el patrón ya establecido en otros métodos de esta
                        # clase (ver, por ejemplo, `lang_override or
                        # self.current_language`).
                        effective_lang = lang or self.current_language
                        web_evidence = search_web_context(
                            query,
                            lang=("en" if effective_lang == "English" else "es"),
                        ) or ""
                        if web_evidence:
                            web_context_used = True
                    except Exception:
                        web_evidence = ""

            fuzz_summary = self._get_fuzz_summary(fuzz_result)
            critique_prompt = (
                f"Hipótesis actual:\n{current_hypothesis}\n\n"
                f"Auditoría de fragilidad/fuzzer:\n{fuzz_summary}\n\n"
            )
            if web_evidence:
                critique_prompt += f"Evidencia web complementaria:\n{web_evidence}\n\n"
            critique_prompt += (
                "Refina y corrige la hipótesis para solucionar las vulnerabilidades o "
                "falta de sustento detectadas. Devuelve ÚNICAMENTE la versión corregida."
            )

            refined = self._call_llm(
                critique_prompt,
                target_model=target_model or self.general_model,
                lang_override=lang,
            )
            if refined and not refined.lstrip().startswith("[ERROR"):
                _, clean_refined = self._split_thought_and_content(refined)
                current_hypothesis = clean_refined or refined
                current_hypothesis, _ = self._strip_system_prompt_echo(current_hypothesis)
                # BLINDAJE (pedido explícito del usuario, 2026-09-15 --
                # "me cobro el doble por algo que no genero pro el
                # auditor de contenido"): este `_call_llm()` pasa por
                # `_call_claude_api_raw` en Cloud, que SIEMPRE manda el
                # schema completo de `tools` sin importar qué pide el
                # prompt -- y este método es un camino de FONDO sin
                # ningún bucle de tool-calling que ejecute lo que el
                # modelo decida invocar. Si el modelo devuelve un
                # `tool_use` en vez de texto (medido en vivo: un
                # `run_cmd` sin sentido), `_call_claude_api_raw` lo
                # reserializa a un bloque ```json {"tool": ...}``` que,
                # sin este blindaje, llegaba TAL CUAL a los DOS
                # llamadores de este método: el bloque de Auditor de
                # contenido en `run_turn` (como respuesta final
                # visible) y `CognitiveGovernor._self_repair` (como
                # "parche sugerido" persistido en WAL/MemoryGraph).
                # Mismo mecanismo que ya arregló patch28
                # (`_strip_unexecuted_trailing_tool_call`) para el
                # bucle principal de tool-calling -- acá nunca se había
                # aplicado. Si esto deja la hipótesis vacía, el
                # llamador de `run_turn` ya tiene el fallback correcto
                # ("la autocrítica no produjo nada usable").
                current_hypothesis = self._strip_unexecuted_trailing_tool_call(
                    current_hypothesis
                )
            else:
                break

        return current_hypothesis, last_fuzz_result, web_context_used

    def _persist_knowledge_node_if_robust(
        self,
        hypothesis: str,
        fuzz_result: Optional[FuzzingResult],
    ) -> bool:
        if fuzz_result is None:
            return False

        if fuzz_result.verdict != FuzzingVerdict.ROBUST:
            return False

        try:
            verification: Dict[str, Any] = {
                "verdict": getattr(
                    fuzz_result.verdict, "value", str(fuzz_result.verdict)
                ),
                "robustness_score": getattr(fuzz_result, "robustness_score", None),
                "elapsed_ms": getattr(fuzz_result, "elapsed_ms", None),
                "detail": self._get_fuzz_summary(fuzz_result),
            }
            provenance: Dict[str, Any] = {
                "engine": "AdversarialFuzzer",
                "produced_by": "Orchestrator._recursive_self_critique",
                "model": self.ollama_model,
                "persisted_at": time.time(),
            }

            node = KnowledgeNode.create(
                domain="conceptual_hypothesis",
                axiom=hypothesis.strip(),
                verification=verification,
                provenance=provenance,
            )
            self._wal.append_knowledge_node(node)
            return True
        except Exception as exc:
            logger.warning("No se pudo persistir KnowledgeNode: %s", exc)
            return False
        
    def _log_generation_perf(
        self,
        data: Dict[str, Any],
        eval_count: int,
        log_cb: Optional[Callable[[str], None]] = None,
        label: str = "LLM",
    ) -> Optional[Dict[str, Any]]:
        """
        BLINDAJE (bug real, MEDIDO): esto SIEMPRE logueó vía `logger.info`
        únicamente — invisible en la terminal gráfica de sovnode_qt.py
        (no existe ningún puente logging->Qt, ver logger.py/_terminal_log:
        la terminal solo recibe lo que se emite explícitamente por la
        señal `log_message`). Para las llamadas de `StreamTurnWorker` que
        SÍ pasan por streaming (`ast_stream.py`) esto ya no importa —
        tienen su propio `_log_stream_perf` — pero cualquier ruta que
        llegue aquí vía `_call_llm_raw` NO-streaming (p.ej. las 3
        llamadas secuenciales/paralelas de `_tree_of_thought_reasoning`,
        el "slow path" — que es exactamente donde más tiempo se gasta y
        menos visibilidad había) seguía sin aparecer nunca en pantalla.
        `log_cb` (opcional, retrocompatible — default None no cambia
        nada para los ~10 llamadores existentes de `_call_llm`/
        `_call_llm_raw` que no lo pasan) permite que el llamador (p.ej.
        StreamTurnWorker, pasando `self.log_message.emit`) reciba el
        mismo mensaje que ya iba solo al log de archivo/consola Python.
        `label` distingue entre llamadas cuando varias comparten turno
        (p.ej. "ToT-A"/"ToT-B"/"ToT-Synthesis").
        """
        try:
            prompt_eval_count = int(data.get("prompt_eval_count", 0) or 0)
            prompt_eval_ns = int(data.get("prompt_eval_duration", 0) or 0)
            eval_ns = int(data.get("eval_duration", 0) or 0)
            load_ns = int(data.get("load_duration", 0) or 0)
        except (TypeError, ValueError):
            return

        if prompt_eval_count <= 0 and eval_count <= 0:
            return

        prefill_s = prompt_eval_ns / 1e9
        decode_s = eval_ns / 1e9
        load_s = load_ns / 1e9

        prefill_tok_s = (prompt_eval_count / prefill_s) if prefill_s > 0 else 0.0
        decode_tok_s = (eval_count / decode_s) if decode_s > 0 else 0.0

        message = (
            f"⚡ [{label}] prefill={prompt_eval_count}tok/{prefill_s:.2f}s "
            f"({prefill_tok_s:.1f}tok/s) | decode={eval_count}tok/{decode_s:.2f}s "
            f"({decode_tok_s:.1f}tok/s) | load={load_s:.2f}s"
        )
        logger.info(message)
        if log_cb is not None:
            with contextlib.suppress(Exception):
                log_cb(message)

        # Diagnóstico de swap de VRAM (Ítem 2 del "Plan de Acción",
        # 2026-09-02) — ver VRAM_SWAP_LOAD_THRESHOLD_S. `data["model"]` es
        # el nombre que OLLAMA MISMO reporta haber usado (más confiable acá
        # que el `target_model` que le pedimos: es lo que de verdad pasó),
        # así que esto detecta swapping sin importar qué llamador dispare
        # cada request. Compara contra la ÚLTIMA llamada completada de
        # CUALQUIER tipo (router 0.5B, RESPONSE_MODEL 7B, o cualquier otro
        # target_model puntual) — dos llamadas seguidas al MISMO modelo con
        # `load_s` alto no cuentan como swap (podría ser el primer arranque
        # de Ollama, no un desalojo); un cambio de modelo con `load_s` por
        # encima del umbral sí es evidencia concreta de que el anterior ya
        # no estaba en VRAM. Nunca lanza ni bloquea el turno — es
        # puramente informativo, mismo criterio que el resto de este
        # método (BLINDAJE de arriba: logger.info() solo no bastaba, por
        # eso también va a log_cb).
        model_name = str(data.get("model") or "")
        if model_name:
            prev_model = self._last_llm_model
            if (
                prev_model is not None
                and prev_model != model_name
                and load_s >= self.VRAM_SWAP_LOAD_THRESHOLD_S
            ):
                swap_message = (
                    f"🔄 [VRAM] {model_name} tardó {load_s:.2f}s en cargar justo "
                    f"después de una llamada a {prev_model} — probable swap de "
                    f"VRAM entre ambos modelos (umbral={self.VRAM_SWAP_LOAD_THRESHOLD_S:.2f}s, "
                    f"SOVNODE_VRAM_SWAP_LOAD_THRESHOLD_S)."
                )
                logger.warning(swap_message)
                if log_cb is not None:
                    with contextlib.suppress(Exception):
                        log_cb(swap_message)
            self._last_llm_model = model_name

        self.last_generation_stats = {
            "label": label,
            "prefill_tok_s": prefill_tok_s,
            "decode_tok_s": decode_tok_s,
            "prompt_eval_count": prompt_eval_count,
            "eval_count": eval_count,
            "load_s": load_s,
            "prefill_s": prefill_s,
            "decode_s": decode_s,
        }
        return self.last_generation_stats

    def set_cloud_backend(
        self,
        enabled: bool,
        api_key: Optional[str] = None,
        model_id: Optional[str] = None,
        provider: Optional[str] = None,
    ) -> None:
        """
        Prende/apaga el motor de Nube (API real de Claude o Gemini, según
        `provider`) y/o actualiza la API key / el modelo objetivo /
        el proveedor. Llamado desde el panel de configuración de
        sovnode_qt.py (sección "Motor de Generación").

        `api_key`/`model_id`/`provider` en `None` dejan el valor actual
        sin tocar — así la UI puede togglear `enabled` sin tener que
        reenviar el resto cada vez (p. ej. para apagar temporalmente sin
        borrar nada).

        `provider` (2026-09-19, patch_orchestrator96 -- ver el BLINDAJE
        junto a `GEMINI_API_BASE`): "anthropic" o "gemini" (cualquier
        otro valor cae a "anthropic", el de siempre, en vez de dejar el
        objeto en un estado no reconocido por el resto del pipeline).
        IMPORTANTE: si el llamador cambia de proveedor SIN mandar
        `model_id` en el mismo llamado, `self.cloud_model_id` queda con
        el modelo del proveedor VIEJO (p. ej. "claude-sonnet-5" al pasar
        a Gemini) -- sovnode_qt.py es responsable de mandar el `model_id`
        correcto del proveedor nuevo junto con el cambio (ver
        `_on_cloud_provider_changed`), pero como red de seguridad
        adicional cualquier lugar que necesite "el modelo default del
        proveedor activo" debe usar `_cloud_default_model_for_provider()`
        en vez de asumir `CLOUD_DEFAULT_MODEL` a secas.
        """
        self.cloud_backend_enabled = bool(enabled)
        if provider is not None:
            self.cloud_provider = (
                self.CLOUD_PROVIDER_GEMINI
                if provider.strip().lower() == self.CLOUD_PROVIDER_GEMINI
                else self.CLOUD_PROVIDER_ANTHROPIC
            )
        if api_key is not None:
            self.cloud_api_key = api_key.strip() or None
        if model_id is not None:
            self.cloud_model_id = (
                model_id.strip() or self._cloud_default_model_for_provider()
            )

    def _cloud_default_model_for_provider(self) -> str:
        """
        Modelo default del proveedor de Nube ACTUALMENTE activo
        (`self.cloud_provider`) -- ver el BLINDAJE junto a
        `GEMINI_API_BASE`. Reemplaza los usos sueltos de
        `self.CLOUD_DEFAULT_MODEL` a secas en cualquier lugar que deba
        funcionar igual de bien con los dos proveedores.
        """
        return (
            self.GEMINI_DEFAULT_MODEL
            if getattr(self, "cloud_provider", self.CLOUD_PROVIDER_ANTHROPIC)
            == self.CLOUD_PROVIDER_GEMINI
            else self.CLOUD_DEFAULT_MODEL
        )

    def _cloud_pricing_table(self) -> Dict[str, Tuple[float, float]]:
        """
        Tabla de precios del proveedor de Nube ACTUALMENTE activo -- ver
        el BLINDAJE junto a `GEMINI_API_BASE`.
        """
        return (
            self.GEMINI_PRICING_USD_PER_MTOK
            if getattr(self, "cloud_provider", self.CLOUD_PROVIDER_ANTHROPIC)
            == self.CLOUD_PROVIDER_GEMINI
            else self.CLOUD_PRICING_USD_PER_MTOK
        )

    def set_cloud_output_budget(self, cents: int) -> None:
        """
        Fija el presupuesto de Sonnet por turno (selector "Presupuesto de
        Sonnet" del panel "Motor de Generación", sovnode_qt.py -- 4
        niveles cualitativos: Bajo=1¢, Medio=2¢, Alto=4¢, Extra=8¢) -- ver
        `_cloud_output_ceiling_tokens`/`_effective_codegen_num_predict`.
        Clampeado a [1, 8] -- 8 (nivel "Extra") es el valor más alto que
        ofrece la UI; un valor fuera de rango (p. ej. QSettings corrupto)
        cae al extremo más cercano en vez de reventar o quedar sin techo.

        AMPLIADO (pedido explícito del usuario, 2026-09-15 -- "entonces
        tendriamos que cambiar el 1-4 centavos por low, medium, high,
        extra"): el rango subía como máximo a 4¢ (~3600 tok), insuficiente
        para un archivo grande de verdad -- se agrega un cuarto nivel
        ("Extra", 8¢) en vez de solo renombrar los 4 que ya había.
        """
        self.cloud_output_budget_cents = min(8, max(1, int(cents)))

    def _reported_model_used(self, active_model: str) -> str:
        """
        Etiqueta real para `TurnTrace.model_used` -- el "Turno completado
        exitosamente usando el modelo: X" que arma sovnode_qt.py
        (log_turn_completed).

        BUG REAL, MEDIDO (log en vivo, 2026-09-14/15, pedido explícito del
        usuario): `active_model` es la etiqueta de RUTEO LOCAL que eligió el
        router (p. ej. 'huihui_ai/qwen2.5-abliterate:7b-instruct') -- pero
        cuando el motor Cloud está activo, `_call_llm_raw` la ignora por
        completo y ejecuta la llamada real contra Claude API
        (`self.cloud_model_id`), de forma transparente para el resto del
        pipeline (ver la nota junto al branch de Cloud en `_call_llm_raw`).
        El log de cada llamada ya lo muestra bien ('☁ Claude API
        (claude-sonnet-5): ...'), pero el mensaje de cierre del turno se
        quedaba mostrando la etiqueta local vieja -- contradice, en la
        misma pantalla, la llamada real que se acaba de loguear arriba.

        `cloud_backend_enabled`/`cloud_api_key` son flags de SESIÓN (el
        toggle del panel 'Motor de Generación'), no por-turno -- si están
        prendidos, toda llamada de generación real de este turno fue a
        Cloud (salvo Router0.5B/VerifyLite/Vision, que fuerzan
        `force_local=True` a propósito y no pasan por este mensaje), así
        que reportar `self.cloud_model_id` acá es exacto, no una
        aproximación.
        """
        if getattr(self, "cloud_backend_enabled", False) and getattr(
            self, "cloud_api_key", None
        ):
            return getattr(self, "cloud_model_id", active_model)
        return active_model

    def _cloud_output_ceiling_tokens(self) -> int:
        """
        Traduce `cloud_output_budget_cents` (1/2/4/8, elegido por el
        usuario en el selector "Presupuesto de Sonnet" del panel "Motor
        de Generación" -- 4 niveles: Bajo/Medio/Alto/Extra) a un techo
        real de `num_predict` para llamadas de codegen a Cloud, usando el
        precio de salida real del modelo activo
        (`CLOUD_PRICING_USD_PER_MTOK`) y reservando
        `CLOUD_OUTPUT_BUDGET_SAFETY_FRACTION` (10%) para los tokens de
        entrada frescos (nunca cacheados del todo -- el mensaje del
        usuario en sí no se cachea).

        Ejemplo con los precios de claude-sonnet-5 ($10/MTok de salida):
        1 centavo (Bajo) -> ~900 tok, 2 (Medio) -> ~1800, 4 (Alto) ->
        ~3600, 8 (Extra) -> ~7200 -- se recalcula en vivo, no son
        constantes fijas, así que un cambio de precio o de modelo Cloud
        no rompe la garantía de "nunca más de N centavos".

        Defensivo (getattr con default) por el mismo motivo que
        `_reported_model_used` -- un Orchestrator de test armado sin
        `__init__` no debe explotar acá.
        """
        return self._cloud_output_ceiling_tokens_for_cents(
            getattr(self, "cloud_output_budget_cents", 1)
        )

    # BLINDAJE (2026-09-18, patch_orchestrator82 -- ver `_elevate_codegen_
    # ceiling_if_needed` más abajo): se saca el cálculo real de
    # `_cloud_output_ceiling_tokens` a este método aparte, parametrizado por
    # `cents` en vez de leer siempre `self.cloud_output_budget_cents`, para
    # poder cotizar "¿cuánto techo real daría el próximo escalón de
    # presupuesto?" sin tocar la selección guardada del usuario. Mismo
    # cálculo exacto, sin cambios de comportamiento para el call-site
    # original (`_cloud_output_ceiling_tokens()` ahora es un wrapper de una
    # línea sobre este método con el cents actual del usuario).
    def _cloud_output_ceiling_tokens_for_cents(self, cents: int) -> int:
        # patch_orchestrator96 (2026-09-19): tabla de precios y modelo
        # default dependen del proveedor activo (Claude/Gemini) -- ver
        # `_cloud_pricing_table`/`_cloud_default_model_for_provider`.
        _default_model = self._cloud_default_model_for_provider()
        _pricing = self._cloud_pricing_table()
        _, price_out = _pricing.get(
            getattr(self, "cloud_model_id", _default_model),
            _pricing[_default_model],
        )
        if price_out <= 0:
            return MemoryGovernor.codegen_num_predict()
        budget_usd = (cents / 100.0) * self.CLOUD_OUTPUT_BUDGET_SAFETY_FRACTION
        return max(1, round(budget_usd / (price_out / 1_000_000.0)))

    # BLINDAJE (2026-09-18, patch_orchestrator82 -- pedido explícito del
    # usuario: "porque mejor no hacemos mas flexible el techo... y que eso
    # aplique para los demas esfuerzos" [los 4 niveles del selector
    # "Presupuesto de Sonnet", no solo "Bajo"]). Contexto: `patch_
    # orchestrator80`/`81` (mismo día) hicieron que CUALQUIER pedido de
    # archivo nuevo cuyo piso estimado (`_min_viable_floor`) supere el techo
    # real del tier elegido corte gratis, sin intentar -- correcto para
    # evitar pagar por intentos condenados, pero el usuario probó "DOOM
    # básico" en "Bajo" y vio que SIEMPRE rebotaba (900 < piso de juego,
    # 1300), sin excepción, aunque otro tier sí hubiera alcanzado.
    #
    # El usuario propuso literalmente un techo "elástico" (p. ej. 700-1100
    # en vez de 900 fijo) -- pero un rango así de chico NO resuelve el caso
    # real (1100 sigue siendo menor a 1300). Se le explicó la disyuntiva
    # real (ver ARCHITECTURE.md item 20) y eligió expresamente: "que Bajo
    # pueda intentar juegos", aceptando que el techo real por tier deja de
    # ser un número fijo y pasa a poder subir hasta el próximo escalón
    # cuando el piso lo exige -- rompiendo a propósito, por elección
    # explícita del usuario, la garantía de "nunca más que N centavos" que
    # `patch_orchestrator16` (BLINDAJE de arriba, "el techo del usuario
    # manda tal cual, sin subirlo nunca") había fijado como invariante. Esa
    # garantía sigue siendo el comportamiento POR DEFECTO -- este método
    # es la única excepción, y solo actúa cuando el turno YA iba a cortar a
    # $0 sin él (nunca sube el techo de un turno que igual iba a andar con
    # el techo normal).
    #
    # Diseño original (arriba): un salto discreto entre 4 números fijos
    # (900/1800/3600/7200) -- funcionaba (retest confirmado: 4/4 turnos de
    # prueba cortaron a $0 correctamente), PERO el usuario retesteó "DOOM
    # básico" en Bajo (elevado a Medio=1800 por este mismo mecanismo) y el
    # `write_file` llegó EXACTO al techo de 1800 sin terminar (JSON cortado
    # a mitad de un string, `_continue_truncated_file_write_locally`
    # tuvo que rescatarlo gratis en Local -- turno `0f02ec00-9052-4f03-
    # b290-fd444fcbdea4`, confirmado por WAL/debug log). El usuario pidió,
    # de nuevo, "un rango... por ejemplo 700 a 1200 tokens en vez de un
    # techo fijo de 900" -- pero pidiéndolo "estricto": no relajar el
    # límite duro, sino hacer más fino CÓMO se elige el techo real dentro
    # (y entre) los niveles.
    #
    # BLINDAJE (2026-09-18, patch_orchestrator83): se generaliza el salto
    # discreto de patch82 a un esquema de RANGOS por nivel. Cada nivel
    # (Bajo/Medio/Alto/Extra) ya no es un solo número -- es un rango
    # `[nominal*0.78, nominal*1.33]` (con nominal=900 para Bajo, esos
    # factores dan exactamente el 700-1200 que pidió el usuario de
    # ejemplo; se aplican por igual a los 4 niveles, pedido explícito:
    # "que eso aplique para los demas esfuerzos"). Cuando un pedido no
    # entra en el techo nominal de su nivel, se busca (empezando por el
    # nivel actual, sin descartarlo de entrada) el PRIMER rango cuyo techo
    # alcance un objetivo con margen chico (`piso * 1.1`, ver el BLINDAJE
    # más abajo sobre por qué es 1.1 y no un multiplicador más grande). Si
    # el rango del nivel actual ya alcanza ese objetivo, se resuelve
    # DENTRO del mismo nivel (sin cambiar de nombre/centavos) con un techo
    # ajustado al objetivo. Si hace falta subir de nivel, en vez de saltar
    # al nominal FIJO del próximo nivel (lo que hacía patch82, y por lo
    # que DOOM quedó pegado exacto a 1800), se usa el TECHO COMPLETO del
    # rango de destino -- para el caso real de DOOM (piso=1300): el rango
    # de Bajo (700-1200) no alcanza el objetivo (1430), se sube a Medio y
    # se usa su techo completo (2394), no un número a mitad de camino --
    # más margen real que el 1800 fijo de antes, sin costo extra a menos
    # que el modelo de verdad necesite ese espacio (el costo real depende
    # de los tokens que se usen, no del techo).
    #
    # Sigue siendo "estricto" en el sentido que pidió el usuario: el techo
    # más alto que puede llegar a usar sigue siendo el máximo del rango de
    # "Extra" (9600, antes 7200) -- un límite duro, no elástico sin fondo.
    # Si ni ESE rango alcanza el objetivo con margen, no hay elevación
    # posible y el turno sigue cortando a $0 exactamente igual que antes
    # de patch82/83 (pedidos genuinamente descomunales siguen sin
    # intentarse a ciegas). La garantía de costo fijo de
    # `patch_orchestrator16` sigue siendo el comportamiento POR DEFECTO
    # para cualquier turno que YA entraba en su nivel -- este mecanismo
    # solo actúa cuando el turno de todos modos iba a cortar a $0 sin él,
    # nunca reduce ni sube el techo de un turno que ya andaba bien.
    #
    # Devuelve `(None, None, techo_original)` si no hizo falta o no fue
    # posible ensanchar/elevar, o `(cents_desde, cents_hacia,
    # techo_final)` si encontró un rango que alcanza -- `cents_desde ==
    # cents_hacia` cuando se resolvió ensanchando el rango del MISMO
    # nivel, sin cambiar de nombre.
    # BLINDAJE (2026-09-18, ajuste sobre patch_orchestrator83 -- verificado
    # con una simulación standalone ANTES de tocar este método real, mismo
    # hábito que el resto de la sesión): la primera versión de este método
    # usaba el MISMO multiplicador (1.5x del piso) tanto para decidir qué
    # rango alcanza como para el techo final -- resultado: como 1.5 > 1.33
    # (el factor máximo del rango), la resolución "dentro del mismo nivel"
    # quedaba matemáticamente INALCANZABLE (código muerto) para cualquier
    # entrada, algo que la simulación de prueba detectó antes de subirlo al
    # dispositivo. Se separan las dos decisiones: `_CODEGEN_ESCALATION_
    # SEARCH_MARGIN_MULTIPLIER` (1.1x, chico) decide SOLO qué rango
    # califica -- deja una ventana real donde un desborde chico se resuelve
    # ensanchando el rango del MISMO nivel (ej. piso=1000 en "Bajo" con
    # rango 700-1200 -> usa 1100, sin cambiar de nivel). Cuando SÍ hace
    # falta subir de nivel, se usa el techo completo del rango de destino
    # (`hi`, no el objetivo con margen chico) -- no hay motivo para
    # contenerse ahí: el costo real depende de los tokens que el modelo
    # termine usando de verdad, no del techo, así que dar más aire dentro
    # del rango ya elegido nunca cuesta más, solo baja el riesgo de pegar
    # contra el techo (el problema real medido con DOOM: piso=1300 con el
    # techo plano de 1800 de patch82 se cortó justo al límite -- con este
    # ajuste, el mismo pedido aterriza en el rango de "Medio" con
    # 2394tok de techo real, no 1800).
    _CLOUD_OUTPUT_BUDGET_CENTS_LADDER: List[int] = [1, 2, 4, 8]
    _CLOUD_OUTPUT_BUDGET_RANGE_MIN_FACTOR: float = 0.78  # 900 -> ~700
    _CLOUD_OUTPUT_BUDGET_RANGE_MAX_FACTOR: float = 1.33  # 900 -> ~1200
    _CODEGEN_ESCALATION_SEARCH_MARGIN_MULTIPLIER: float = 1.1

    def _codegen_range_for_cents(self, cents: int) -> Tuple[int, int]:
        nominal = self._cloud_output_ceiling_tokens_for_cents(cents)
        lo = max(1, round(nominal * self._CLOUD_OUTPUT_BUDGET_RANGE_MIN_FACTOR))
        hi = max(lo, round(nominal * self._CLOUD_OUTPUT_BUDGET_RANGE_MAX_FACTOR))
        return lo, hi

    def _elevate_codegen_ceiling_if_needed(
        self, gen_predict: int, min_viable_floor: int
    ) -> Tuple[Optional[int], Optional[int], int]:
        if gen_predict >= min_viable_floor:
            return None, None, gen_predict
        current_cents = getattr(self, "cloud_output_budget_cents", 1)
        margin_target = max(
            min_viable_floor,
            round(min_viable_floor * self._CODEGEN_ESCALATION_SEARCH_MARGIN_MULTIPLIER),
        )
        for candidate_cents in self._CLOUD_OUTPUT_BUDGET_CENTS_LADDER:
            if candidate_cents < current_cents:
                continue
            lo, hi = self._codegen_range_for_cents(candidate_cents)
            if hi >= margin_target:
                if candidate_cents == current_cents:
                    new_ceiling = max(lo, min(hi, margin_target))
                else:
                    new_ceiling = hi
                return current_cents, candidate_cents, new_ceiling
        return None, None, gen_predict

    _CLOUD_OUTPUT_BUDGET_CENTS_LABELS: Dict[int, str] = {
        1: "Bajo", 2: "Medio", 4: "Alto", 8: "Extra",
    }

    # Piso técnico mínimo de tokens para CUALQUIER versión funcional de un
    # pedido de código -- aunque se recorte el alcance al hueso (2026-09-16,
    # sesión de Cowork; pedido explícito del usuario: "cuando ya sea
    # tecnológicamente no posible, que el modelo lo detecte al principio y
    # no gaste nada de tokens"). Complementa, no reemplaza, al bloque
    # [OUTPUT BUDGET]/[PRESUPUESTO DE SALIDA] de más abajo en `run_turn`:
    # ese bloque negocia CUÁNTO alcance recortar (menos tropas, menos
    # torres, IA más simple) para un pedido que SÍ entra si se recorta.
    # Este piso mide otra cosa -- el costo FIJO de andamiaje que cualquier
    # cosa de esa tecnología necesita solo para existir como programa que
    # corre (ventana + loop de eventos + una entidad mínima, para un
    # juego con pygame), sin importar cuánto se reduzca el resto. Si el
    # techo real queda por debajo de ESTE piso, ningún recorte de alcance
    # lo salva -- generar igual solo quema tokens (con Cloud activo,
    # plata real del usuario) en algo condenado a salir roto o a mitad.
    #
    # Estimación heurística por palabras clave (mismo estilo que
    # `router.py`: regex determinista, sin LLM, sin ambigüedad de
    # puntaje) -- a diferencia de la mayoría de las constantes de este
    # archivo, que citan un bug real medido por WAL, estos números NO
    # están calibrados todavía contra generaciones reales. Son un primer
    # piso razonable, no un dato confirmado -- antes de confiar en el
    # valor exacto a largo plazo, valdría medir cuántos tokens usa de
    # verdad un `write_file` real de cada categoría (WAL) y ajustar acá.
    _MIN_VIABLE_FLOOR_DEFAULT: int = 120

    # BLINDAJE (2026-09-18, patch_orchestrator71 -- se saca este patrón
    # del literal de `_MIN_VIABLE_FLOOR_PATTERNS` de más abajo y se
    # nombra acá aparte, ÚNICA fuente de verdad, para poder reusarlo
